{"script":"() => {
  const cards = document.querySelectorAll('a[id^="mntl-card-list-card--extendable"]');
  const results = [];
  cards.forEach(card => {
    const title = card.querySelector('span[id^="mntl-card__heading"]')?.textContent?.trim() || '';
    const ratingDiv = card.querySelector('div[id^="mntl-recipe-star-rating_"]');
    const ratingText = ratingDiv?.textContent?.trim() || '';
    const ratingCount = card.querySelector('div[id^="mntl-recipe-card-meta_"] > div:last-child')?.textContent?.trim() || '';
    const href = card.getAttribute('href');
    if (title && (ratingText || ratingCount)) {
      results.push({title, ratingText, ratingCount, href});
    }
  });
  return results;
}"}

