{"script":"() => {
  const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
  const results = [];
  cards.forEach(card => {
    const spans = card.querySelectorAll('span');
    let title = '';
    for (const span of spans) {
      const txt = span.textContent.trim();
      if (txt && txt.length > 5 && !['Ratings'].includes(txt)) {
        title = txt;
        break;
      }
    }
    const allText = card.textContent;
    const href = card.getAttribute('href');
    if (title) {
      results.push({title, fullText: allText.substring(0, 300), href});
    }
  });
  return results;
}"}

